class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    dummy = ListNode(0)
    p = dummy
    for v in vals:
        p.next = ListNode(v)
        p = p.next
    return dummy.next


def to_vals(head):
    res = []
    while head:
        res.append(head.val)
        head = head.next
    return res


def reverse_list(head):
    vals = to_vals(head)
    return build(vals[::-1])


def main():
    line = input().strip()
    vals = list(map(int, line.split())) if line else []
    print(' '.join(map(str, to_vals(reverse_list(build(vals))))))


if __name__ == "__main__":
